rollback.sql:
DO $$
BEGIN
    IF EXISTS (
        SELECT 1
        FROM material material_to_remove
        WHERE material_to_remove.code = 'STAINLESS_STEEL'
          AND (
            EXISTS (
                SELECT 1 FROM watch_details details
                WHERE details.case_material_id = material_to_remove.id
                   OR details.strap_material_id = material_to_remove.id
            )
            OR EXISTS (
                SELECT 1 FROM interior_clock_details details
                WHERE details.case_material_id = material_to_remove.id
            )
            OR EXISTS (
                SELECT 1 FROM accessory_details details
                WHERE details.case_material_id = material_to_remove.id
                   OR details.insert_material_id = material_to_remove.id
            )
          )
    ) THEN
        RAISE EXCEPTION 'Cannot roll back stainless steel material while products reference it';
    END IF;

    DELETE FROM material WHERE code = 'STAINLESS_STEEL';
END $$;

changeSet.sql:
ALTER TABLE product DROP CONSTRAINT IF EXISTS chk_product_kaspi_url_canonical;
ALTER TABLE product
    ADD CONSTRAINT chk_product_kaspi_url_canonical
    CHECK (
        kaspi_url IS NULL
        OR kaspi_url = 'https://kaspi.kz/shop/m/1433003/products?productCode=110688026&masterSku=110688026&merchantSku=AM%2b003%2bH%2bBRONZE&tabId=PRODUCT&started_by=shop_product&ref=shared_link&sessionId=b58a609e-9e07-4c3b-b683-fcf5ccec61d51785317673&link_source=chrome'
        OR kaspi_url ~ '^https://(www\.)?kaspi\.kz/shop/p/[^[:space:]?#]+/?([?][^[:space:]#]*)?$'
    );

rollback.sql:
ALTER TABLE product DROP CONSTRAINT IF EXISTS chk_product_kaspi_url_canonical;
DO $$
BEGIN
    IF EXISTS (
        SELECT 1
        FROM product
        WHERE kaspi_url IS NOT NULL
          AND kaspi_url != 'https://kaspi.kz/shop/m/1433003/products?productCode=110688026&masterSku=110688026&merchantSku=AM%2b003%2bH%2bBRONZE&tabId=PRODUCT&started_by=shop_product&ref=shared_link&sessionId=b58a609e-9e07-4c3b-b683-fcf5ccec61d51785317673&link_source=chrome'
    ) THEN
        RAISE EXCEPTION 'Cannot roll back Kaspi product source links without losing product-specific URLs';
    END IF;
END $$;
ALTER TABLE product
    ADD CONSTRAINT chk_product_kaspi_url_canonical
    CHECK (
        kaspi_url IS NULL
        OR kaspi_url = 'https://kaspi.kz/shop/m/1433003/products?productCode=110688026&masterSku=110688026&merchantSku=AM%2b003%2bH%2bBRONZE&tabId=PRODUCT&started_by=shop_product&ref=shared_link&sessionId=b58a609e-9e07-4c3b-b683-fcf5ccec61d51785317673&link_source=chrome'
    );
